const toObjectArray = value => {
  if (Array.isArray(value)) return value.filter(item => item && typeof item === 'object');
  if (value && typeof value === 'object') return Object.values(value).filter(item => item && typeof item === 'object');
  return [];
};

const firstText = (...values) => {
  for (const value of values) {
    if (value === null || value === undefined) continue;
    const text = String(value).trim();
    if (text) return text;
  }
  return '';
};

const normalizeKey = value => firstText(value).toLowerCase().replace(/[^a-z0-9]+/g, '');
const generatedBacklog = generated.backlog && typeof generated.backlog === 'object' ? generated.backlog : {};

const normalizeEpic = (epic, index) => {
  const copy = { ...epic };
  const epicId = firstText(copy.epicCorrelationId, copy.epicId, copy.id, copy.key, copy.referenceId, 'EPIC-' + String(index + 1).padStart(3, '0'));
  copy.epicCorrelationId = firstText(copy.epicCorrelationId, copy.epicId, copy.id, copy.key, epicId);
  copy.epicId = firstText(copy.epicId, copy.epicCorrelationId, epicId);
  copy.epicName = firstText(copy.epicName, copy.name, copy.title, copy.feature, copy.summary, 'Generated Epic ' + String(index + 1));
  copy.epicSummary = firstText(copy.epicSummary, copy.epicDescription, copy.description, copy.businessOutcome, copy.summary);
  copy.businessOutcome = firstText(copy.businessOutcome, copy.businessObjective, copy.outcome, copy.epicSummary);
  return copy;
};

const normalizeStory = (story, epic, index) => {
  const copy = { ...story };
  const epicId = firstText(epic?.epicCorrelationId, epic?.epicId, copy.epicCorrelationId, copy.epicId, copy.parentEpicId, 'EPIC-001');
  const storyId = firstText(copy.storyCorrelationId, copy.userStoryId, copy.storyId, copy.id, copy.key, epicId + '-US-' + String(index + 1).padStart(3, '0'));
  copy.storyCorrelationId = firstText(copy.storyCorrelationId, copy.userStoryId, copy.storyId, storyId);
  copy.userStoryId = firstText(copy.userStoryId, copy.storyCorrelationId, storyId);
  copy.epicCorrelationId = firstText(copy.epicCorrelationId, copy.epicId, copy.parentEpicId, epicId);
  copy.epicId = firstText(copy.epicId, copy.epicCorrelationId, epicId);
  copy.summary = firstText(copy.summary, copy.title, copy.name, copy.feature, String(copy.userStory || '').slice(0, 120));
  copy.feature = firstText(copy.feature, copy.summary, epic?.epicName);
  copy.userStory = firstText(copy.userStory, copy.story, copy.description, copy.userStoryDescription, copy.summary);
  copy.userStoryDescription = firstText(copy.userStoryDescription, copy.description, copy.userStory);
  copy.acceptanceCriteria = copy.acceptanceCriteria ?? copy.acceptance_criteria ?? copy.ac ?? copy.criteria ?? [];
  copy.sourceReferences = copy.sourceReferences ?? copy.sourceTraceability ?? copy.traceability ?? [];
  return copy;
};

let epics = [
  ...toObjectArray(generated.epics),
  ...toObjectArray(generatedBacklog.epics),
  ...toObjectArray(generated.features),
  ...toObjectArray(generatedBacklog.features)
].map(normalizeEpic);

if (context.updateMode && epics.length === 0) {
  const previousEpics = previousBacklogEpicsFromUpdateContext(context);
  epics = previousEpics.map((epic, index) => normalizeEpic({
    ...epic,
    epicCorrelationId: firstText(epic.epicCorrelationId, epic.epicId, epic.jiraEpicKey, epic.key),
    epicId: firstText(epic.epicId, epic.epicCorrelationId, epic.jiraEpicKey, epic.key),
    action: firstText(epic.action, 'reused')
  }, index));
}

const seenEpicIds = new Set();
epics = epics.filter(epic => {
  const key = normalizeKey(firstText(epic.epicCorrelationId, epic.epicId, epic.epicName));
  if (!key || seenEpicIds.has(key)) return false;
  seenEpicIds.add(key);
  return true;
});

for (const [epicIndex, epic] of epics.entries()) {
  const nestedStories = [
    ...toObjectArray(epic.stories),
    ...toObjectArray(epic.userStories),
    ...toObjectArray(epic.childStories),
    ...toObjectArray(epic.children),
    ...toObjectArray(epic.items)
  ];
  epic.stories = nestedStories.map((story, storyIndex) => normalizeStory(story, epic, storyIndex));
}

const topLevelStories = [
  ...toObjectArray(generated.stories),
  ...toObjectArray(generated.userStories),
  ...toObjectArray(generatedBacklog.stories),
  ...toObjectArray(generatedBacklog.userStories)
];

const epicKeys = epic => new Set([
  epic.epicCorrelationId,
  epic.epicId,
  epic.id,
  epic.key,
  epic.epicName,
  epic.name,
  epic.title,
  epic.feature,
  epic.summary
].map(normalizeKey).filter(Boolean));

const storyEpicKeys = story => [
  story.epicCorrelationId,
  story.epicId,
  story.parentEpicId,
  story.parentEpicCorrelationId,
  story.epicName,
  story.epic,
  story.feature,
  story.module,
  story.domain
].map(normalizeKey).filter(Boolean);

const groupUnmatchedStories = new Map();
for (const rawStory of topLevelStories) {
  const keys = storyEpicKeys(rawStory);
  let targetEpic = epics.find(epic => {
    const keysForEpic = epicKeys(epic);
    return keys.some(key => keysForEpic.has(key));
  });

  if (!targetEpic && epics.length === 1) targetEpic = epics[0];

  if (targetEpic) {
    targetEpic.stories.push(normalizeStory(rawStory, targetEpic, targetEpic.stories.length));
  } else {
    const groupName = firstText(rawStory.epicName, rawStory.epic, rawStory.feature, rawStory.module, rawStory.domain, 'Generated Backlog');
    const key = normalizeKey(groupName) || 'generatedbacklog';
    if (!groupUnmatchedStories.has(key)) groupUnmatchedStories.set(key, { name: groupName, stories: [] });
    groupUnmatchedStories.get(key).stories.push(rawStory);
  }
}

for (const group of groupUnmatchedStories.values()) {
  const epic = normalizeEpic({
    epicName: group.name,
    epicSummary: 'Generated from top-level user stories returned by the backlog model.',
    businessOutcome: 'Create a Jira-ready backlog from retrieved project evidence.'
  }, epics.length);
  epic.stories = group.stories.map((story, storyIndex) => normalizeStory(story, epic, storyIndex));
  epics.push(epic);
}

epics = mergePreviousStoriesForUpdateMode(epics, context);
generated.epics = epics;
if (context.updateMode && !generated.document.updateSummary) {
  const updateContext = context.updateContext && typeof context.updateContext === 'object' ? context.updateContext : {};
  generated.document.updateSummary = {
    previousJobId: updateContext.previousJobId || context.updateOfJobId || null,
    reusedEpicCount: previousBacklogEpicsFromUpdateContext(context).length,
    reusedStoryCount: previousBacklogStoriesFromUpdateContext(context).length,
    createdEpicCount: 0,
    createdStoryCount: 0,
    updatedEpicCount: 0,
    updatedStoryCount: 0,
    note: 'Previous backlog snapshot merged for update-mode validation and Jira reuse.'
  };
}
const fatalErrors = [];

const normalizeArray = value => {
  if (Array.isArray(value)) return value.map(v => typeof v === 'string' ? v.trim() : JSON.stringify(v)).filter(Boolean);
  if (typeof value === 'string' && value.trim()) return [value.trim()];
  return [];
};

function normalizeCoverageStatus(value) {
  const raw = String(value || '').trim().toLowerCase();
  if (raw.includes('exclude') || raw === 'n/a' || raw === 'not applicable') return 'excluded';
  if (raw.includes('partial') || raw.includes('at risk')) return 'partial';
  if (raw.includes('miss') || raw.includes('gap') || raw.includes('unmapped') || raw.includes('not covered')) return 'missing';
  if (raw.includes('cover') || raw.includes('mapped') || raw.includes('included')) return 'covered';
  return 'unknown';
}

function textList(...values) {
  return [...new Set(values.flatMap(value => {
    if (Array.isArray(value)) return value;
    if (value === null || value === undefined) return [];
    return String(value).split(/[;,]/);
  }).map(value => String(value || '').trim()).filter(Boolean))];
}

function normalizeCoverageLedger(value) {
  const rows = Array.isArray(value)
    ? value
    : value && typeof value === 'object'
      ? Object.values(value)
      : [];

  return rows
    .filter(row => row && typeof row === 'object')
    .map((row, index) => {
      const mappedEpicIds = textList(row.mappedEpicIds, row.epicCorrelationIds, row.epicIds, row.epics, row.epicId, row.epicCorrelationId);
      const mappedStoryIds = textList(row.mappedStoryIds, row.storyCorrelationIds, row.storyIds, row.userStoryIds, row.stories, row.storyId, row.storyCorrelationId);
      return {
        coverageId: firstText(row.coverageId, row.id, row.requirementId, 'BCOV-' + String(index + 1).padStart(3, '0')),
        moduleRequirement: firstText(row.moduleRequirement, row.module, row.requirement, row.capability, row.title, row.name),
        sourceReference: firstText(row.sourceReference, row.source, row.sourceRef, row.sourceRefs, row.evidence),
        mappedEpicIds,
        mappedStoryIds,
        coverageStatus: normalizeCoverageStatus(row.coverageStatus || row.status || row.coverage),
        notes: firstText(row.notes, row.rationale, row.reason, row.exclusionReason)
      };
    })
    .filter(row => row.coverageId || row.moduleRequirement);
}


function previousBacklogStoriesFromUpdateContext(context) {
  const updateContext = context.updateContext && typeof context.updateContext === 'object' ? context.updateContext : {};
  const previousStories = Array.isArray(updateContext.previousStories) ? updateContext.previousStories : [];
  return previousStories.filter(story => story && typeof story === 'object');
}

function previousBacklogEpicsFromUpdateContext(context) {
  const updateContext = context.updateContext && typeof context.updateContext === 'object' ? context.updateContext : {};
  const previousEpics = Array.isArray(updateContext.previousEpics) ? updateContext.previousEpics : [];
  return previousEpics.filter(epic => epic && typeof epic === 'object');
}

function mergePreviousStoriesForUpdateMode(epics, context) {
  if (!context.updateMode) return epics;
  const previousStories = previousBacklogStoriesFromUpdateContext(context);
  if (!previousStories.length) return epics;

  const previousEpics = previousBacklogEpicsFromUpdateContext(context);
  const epicByCorrelation = new Map();
  const epicByJiraKey = new Map();
  const epicByStableLabel = new Map();

  for (const epic of epics) {
    const correlation = normalizeKey(firstText(epic.epicCorrelationId, epic.epicId, epic.id));
    const jiraKey = normalizeKey(firstText(epic.jiraEpicKey, epic.epicKey, epic.key));
    const stable = normalizeKey(firstText(epic.stableLabel));
    if (correlation) epicByCorrelation.set(correlation, epic);
    if (jiraKey) epicByJiraKey.set(jiraKey, epic);
    if (stable) epicByStableLabel.set(stable, epic);
  }

  const enrichEpicFromSnapshot = (epic, snapshot) => {
    if (!snapshot) return;
    epic.jiraEpicKey = firstText(epic.jiraEpicKey, snapshot.jiraEpicKey, snapshot.epicKey, snapshot.key);
    epic.jiraEpicId = firstText(epic.jiraEpicId, snapshot.jiraEpicId, snapshot.epicId, snapshot.id);
    epic.stableLabel = firstText(epic.stableLabel, snapshot.stableLabel);
    epic.epicSummary = firstText(epic.epicSummary, snapshot.epicSummary, snapshot.summary);
    epic.businessOutcome = firstText(epic.businessOutcome, snapshot.businessOutcome, snapshot.businessObjective);
    epic.sourceReferences = textList(epic.sourceReferences, snapshot.sourceReferences, snapshot.sourceTraceability);
  };

  for (const epic of epics) {
    const match = previousEpics.find(snapshot => {
      const snapshotCorrelation = normalizeKey(firstText(snapshot.epicCorrelationId, snapshot.epicId, snapshot.id));
      const snapshotKey = normalizeKey(firstText(snapshot.jiraEpicKey, snapshot.epicKey, snapshot.key));
      const snapshotStable = normalizeKey(firstText(snapshot.stableLabel));
      return (
        (snapshotCorrelation && snapshotCorrelation === normalizeKey(firstText(epic.epicCorrelationId, epic.epicId, epic.id))) ||
        (snapshotKey && snapshotKey === normalizeKey(firstText(epic.jiraEpicKey, epic.epicKey, epic.key))) ||
        (snapshotStable && snapshotStable === normalizeKey(firstText(epic.stableLabel)))
      );
    });
    enrichEpicFromSnapshot(epic, match);
  }

  const existingStoryKeys = new Set();
  for (const epic of epics) {
    epic.stories = Array.isArray(epic.stories) ? epic.stories : [];
    for (const story of epic.stories) {
      const key = normalizeKey(firstText(story.storyCorrelationId, story.userStoryId, story.storyId, story.id, story.jiraStoryKey, story.storyKey, story.stableLabel));
      if (key) existingStoryKeys.add(key);
    }
  }

  const findTargetEpic = (story) => {
    const parentCorrelation = normalizeKey(firstText(story.parentEpicCorrelationId, story.epicCorrelationId, story.epicId, story.parentEpicId));
    const parentKey = normalizeKey(firstText(story.parentEpicKey, story.jiraEpicKey, story.epicKey));
    const parentStable = normalizeKey(firstText(story.parentEpicStableLabel, story.epicStableLabel));
    return epicByCorrelation.get(parentCorrelation) || epicByJiraKey.get(parentKey) || epicByStableLabel.get(parentStable) || null;
  };

  for (const rawStory of previousStories) {
    const storyKey = normalizeKey(firstText(rawStory.storyCorrelationId, rawStory.userStoryId, rawStory.storyId, rawStory.id, rawStory.jiraStoryKey, rawStory.storyKey, rawStory.stableLabel));
    if (storyKey && existingStoryKeys.has(storyKey)) continue;
    const targetEpic = findTargetEpic(rawStory);
    if (!targetEpic) continue;
    const story = normalizeStory(rawStory, targetEpic, targetEpic.stories.length);
    story.jiraStoryKey = firstText(story.jiraStoryKey, rawStory.jiraStoryKey, rawStory.storyKey, rawStory.key);
    story.jiraStoryId = firstText(story.jiraStoryId, rawStory.jiraStoryId, rawStory.storyId, rawStory.id);
    story.stableLabel = firstText(story.stableLabel, rawStory.stableLabel);
    story.action = firstText(story.action, rawStory.action, 'reused');
    story.acceptanceCriteria = textList(story.acceptanceCriteria, rawStory.acceptanceCriteria, rawStory.acceptance_criteria);
    story.sourceReferences = textList(story.sourceReferences, rawStory.sourceReferences, rawStory.sourceTraceability, targetEpic.sourceReferences);
    targetEpic.stories.push(story);
    if (storyKey) existingStoryKeys.add(storyKey);
  }

  return epics;
}

function normalizeBatchPlan(value, coverageLedger) {
  const rows = Array.isArray(value?.modules)
    ? value.modules
    : Array.isArray(value?.batches)
      ? value.batches
      : Array.isArray(value)
        ? value
        : [];
  const modules = rows.length ? rows : coverageLedger.map(row => ({
    batchId: row.coverageId,
    module: row.moduleRequirement,
    sourceReferences: [row.sourceReference].filter(Boolean),
    intendedCoverageIds: [row.coverageId],
    status: row.coverageStatus
  }));
  return {
    version: 'backlog-batch-progress-v1',
    mode: 'internal_retry',
    modules: modules
      .filter(row => row && typeof row === 'object')
      .map((row, index) => ({
        batchId: firstText(row.batchId, row.id, row.coverageId, 'BATCH-' + String(index + 1).padStart(3, '0')),
        module: firstText(row.module, row.name, row.moduleRequirement, row.requirement, 'Module ' + String(index + 1)),
        sourceReferences: textList(row.sourceReferences, row.sourceReference, row.sources, row.evidence),
        intendedCoverageIds: textList(row.intendedCoverageIds, row.coverageIds, row.coverageId),
        status: normalizeCoverageStatus(row.status || row.coverageStatus || row.result || 'covered'),
        notes: firstText(row.notes, row.summary, row.resultNotes)
      }))
  };
}

function summarizeBatchPlan(batchPlan, coverageLedger, retryBatchesValue) {
  const retryRows = Array.isArray(retryBatchesValue)
    ? retryBatchesValue
    : retryBatchesValue && typeof retryBatchesValue === 'object'
      ? Object.values(retryBatchesValue)
      : [];
  const retryIds = new Set(retryRows.flatMap(row => textList(row.batchId, row.id, row.coverageId, row.coverageIds, row.module, row.moduleRequirement)).map(normalizeKey));
  const coverageById = new Map(coverageLedger.map(row => [normalizeKey(row.coverageId), row]));
  const batches = (batchPlan.modules || []).map(batch => {
    const coverageRows = batch.intendedCoverageIds
      .map(id => coverageById.get(normalizeKey(id)))
      .filter(Boolean);
    const statuses = coverageRows.length ? coverageRows.map(row => row.coverageStatus) : [batch.status];
    const status = statuses.includes('missing') || statuses.includes('unknown')
      ? 'missing'
      : statuses.includes('partial')
        ? 'partial'
        : statuses.includes('excluded')
          ? 'excluded'
          : 'covered';
    const retried = retryIds.has(normalizeKey(batch.batchId)) || retryIds.has(normalizeKey(batch.module)) || batch.intendedCoverageIds.some(id => retryIds.has(normalizeKey(id)));
    return {
      ...batch,
      status,
      retried,
