let parsed;
try {
  parsed = parseCandidate(raw);
} catch (error) {
  throw new Error(error.message);
}

const generated = parsed.output && typeof parsed.output === 'object' ? parsed.output : parsed;
if (!generated.document || typeof generated.document !== 'object') generated.document = {};

const hasItems = value => Array.isArray(value) && value.length > 0;
let contextForShape = {};
try { contextForShape = $('Build Live Update Context').first().json || {}; } catch (error) {
  try { contextForShape = $('Check Chroma Retrieval Quality').first().json || {}; } catch (ignored) {}
